import { Group, Mesh, PlaneGeometry, DoubleSide } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, vec2, vec3, color, sin, fract, dot, float, Fn } from 'three/tsl';
import { gsap } from 'gsap';

const PALETTE = {
  ink: '#16161d',
  paper: '#e8ecf2',
  accent: '#ff2a38',
  surface: '#0b0b10',
};

// subtle procedural grain, kept ultra-low amplitude so it never reads as noise-pollution
const grainNoise = Fn(([uvNode]) => {
  const n = fract(sin(dot(uvNode, vec2(12.9898, 78.233))).mul(43758.5453123));
  return n;
});

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();
  group.name = 'pricing-card-1-label';

  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [
      { text: 'Pricing 1', role: 'headline', typography: { fontSize: 39 } },
    ];
  const headlineItem = items.find((i) => i.role === 'headline') ?? items[0];
  const headlineText = headlineItem?.text ?? 'Pricing 1';
  const headlineSize = headlineItem?.typography?.fontSize ?? 39;

  const disposables = [];

  // --- engineered gradient card backdrop -------------------------------
  const cardW = 1.7;
  const cardH = 0.62;
  const cardGeo = new THREE.PlaneGeometry(cardW, cardH);
  const cardMat = new MeshBasicNodeMaterial();

  const uvNode = uv();
  const top = color(PALETTE.ink);
  const bottom = color(PALETTE.surface);
  const gradient = mix(bottom, top, uvNode.y);
  const grain = grainNoise(uvNode.mul(420.0)).sub(0.5).mul(0.035);
  cardMat.colorNode = gradient.add(vec3(grain, grain, grain));
  cardMat.side = DoubleSide;

  const cardMesh = new THREE.Mesh(cardGeo, cardMat);
  cardMesh.position.set(0, 0, 0);
  group.add(cardMesh);
  disposables.push(() => cardGeo.dispose(), () => cardMat.dispose());

  // --- thin accent underline (single accent element, tiny frame %) ----
  const underlineGeo = new THREE.PlaneGeometry(0.5, 0.018);
  const underlineMat = new MeshBasicNodeMaterial();
  underlineMat.colorNode = color(PALETTE.accent);
  const underlineMesh = new THREE.Mesh(underlineGeo, underlineMat);
  underlineMesh.position.set(-cardW / 2 + 0.35, -cardH / 2 + 0.09, 0.002);
  group.add(underlineMesh);
  disposables.push(() => underlineGeo.dispose(), () => underlineMat.dispose());

  // --- decorative orb texture, subdued so it never outshines the text --
  const decorGeo = new THREE.PlaneGeometry(0.38, 0.38);
  const decorMat = new MeshBasicNodeMaterial();
  decorMat.transparent = true;
  decorMat.opacity = 0.5;
  const decorMesh = new THREE.Mesh(decorGeo, decorMat);
  decorMesh.position.set(cardW / 2 - 0.32, 0.02, 0.002);
  group.add(decorMesh);
  disposables.push(() => decorGeo.dispose(), () => decorMat.dispose());

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      decorMat.map = tex;
      decorMat.needsUpdate = true;
      disposables.push(() => tex.dispose());
    });
  }

  // --- headline text ("Pricing 1"), brightest element on this label ----
  const textNode = ctx.fontAtlas.createText(headlineText, {
    fontSize: headlineSize,
    color: PALETTE.paper,
    align: 'left',
  });
  textNode.position.set(-cardW / 2 + 0.18, -0.02, 0.01);
  group.add(textNode);

  // --- weighted-settle entrance (static composition, single motion) ----
  group.scale.setScalar(0.001);
  group.position.z += 0; // no scenePosition re-application
  const startY = group.position.y;

  const tl = gsap.timeline();
  tl.to(group.scale, {
    x: 1.04,
    y: 1.04,
    z: 1.04,
    duration: 0.6,
    ease: 'power3.out',
  }).to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'power4.out',
  });

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    tl.kill();
    disposables.forEach((fn) => {
      try {
        fn();
      } catch (e) {
        // no-op, best-effort disposal
      }
    });
    group.traverse((obj) => {
      if (obj.geometry && typeof obj.geometry.dispose === 'function') {
        obj.geometry.dispose();
      }
      if (obj.material && typeof obj.material.dispose === 'function') {
        obj.material.dispose();
      }
    });
  };

  return group;
}
